pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testFuzz_property(uint256 amount, address receiver) public {
        vm.assume(receiver != address(0));
        vm.assume(receiver.code.length == 0); // plain EOA-style recipient
        vm.assume(uint160(receiver) > 0xff); // avoid precompiles that revert on transfer
        amount = bound(amount, 1, address(c).balance == 0 ? type(uint256).max : type(uint256).max);
        vm.deal(address(c), amount);
        uint256 before = receiver.balance;
        bool ok;
        try c.sendTo(receiver, amount) { ok = true; } catch { ok = false; }
        assertTrue(!ok || (receiver.balance - before == amount));
    }
}
